CustomField.formula:
IF(
/*If Account is Country Parent, stores AMD value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), AMD__c,
IF(
/*If Account is Sales site, stores Country Parent Account's AMD__c by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.AMD__c,
IF(
/*If Account is Parent HQ, stores Country Parent Account's AMD__c by traversing one level up the hierarchy*/
ISPICKVAL(IM_Hierarchy_Level__c, 'Parent HQ'), Parent.AMD__c,AMD__c)))
